/**
 * traditions.ts — 中国传统条目数据
 *
 * 12 个子分类（与用户的"全传统"板块列表一一对应）：
 *  - history 子分类 33 条（3 综合主题 + 30 朝代，按《半小时漫画中国史》目录）
 *  - geography-regional 子分类 30 条（按"中国人的家"目录）
 *  - 其他 9 子分类各 3-4 条（philosophy / tech 各 4，其余 3）
 *  - 总计 98 条种子数据
 *
 * 字段：
 *  - id: kebab-case slug
 *  - category: TraditionCategory（见下）
 *  - title: 中文标题
 *  - summary: 40-100 字中文摘要
 *  - era: 主要朝代/年代范围（可选）
 *  - figure: 关键人物（可选）
 *  - imageKeyword: Bing 检索关键词（可选）
 *  - imageUrl: 公共版权图片 URL（可选，Wikimedia Commons 优先）
 *  - fullContent?: 详版（100-200 字，弹窗用）
 */

/** 12 个传统子分类（与用户的"全传统"板块列表一一对应） */
export const TRADITION_CATEGORIES = [
  'history',    // 中国人的历史
  'geography-regional', // 中国人的家（地域文化）
  'myth',       // 中国人的神话
  'philosophy', // 中国人的哲学
  'script',     // 中国人的文字
  'literature', // 中国人的文学
  'art',        // 中国人的艺术
  'calendar',   // 中国人的历法和节气
  'ritual',     // 中国人的礼仪与制度
  'food',       // 中国人的衣食
  'housing',    // 中国人的住行
  'tech',       // 中国人的科技
] as const
export type TraditionCategory = typeof TRADITION_CATEGORIES[number]

/** 单条传统条目 */
export interface TraditionItem {
  id: string
  category: TraditionCategory
  title: string
  summary: string           // 50-100 字摘要
  era?: string              // 主要朝代，如 "春秋战国" / "唐宋" / "先秦"
  figure?: string           // 关键人物（可选）
  imageKeyword?: string     // Bing 检索关键词（可选）
  imageUrl?: string         // 公共版权图片 URL（可选，Wikimedia Commons 优先）
  fullContent?: string      // 弹窗正文 100-300 字（可选）
}

/** 种子数据：每类 3-4 条，共 41 条（按史实） */
export const TRADITIONS: TraditionItem[] = [
  // history (4)
  { id: 'tr-history-intro', category: 'history', title: '引子', summary: '8000 多年前的"擀面杖" — 远古人类最早的研磨工具，文明从一块磨石开始。', era: '8000 BC 前', imageKeyword: 'ancient grinding stone tool neolithic china', fullContent: '在新石器时代早期，生活在黄河流域的先民已经学会用石头研磨谷物。这根看似普通的"擀面杖"，实则是人类从采集走向定居、从狩猎迈向农耕的关键工具。它意味着人类开始改造自然、储存食物，也为后来陶器与农业的诞生埋下伏笔。这是最朴素的文明起点。' },
  { id: 'tr-history-yanying', category: 'history', title: '炎黄子孙', summary: '为什么我们都是炎黄子孙？传说中两个部落联盟奠定了华夏族群基础。', era: '约 BC 5000', figure: '炎帝 / 黄帝', imageKeyword: 'yan di huang di tribal legends china', fullContent: '传说炎帝（神农氏）尝百草、发明农业，黄帝轩辕氏造车舟、创文字。两个部落联盟在黄河中上游崛起，经过阪泉之战、涿鹿之战后融合为一。蚩尤部落战败后部分融入华夏。九黎、三苗、羌、狄等族群也在这一时期与华夏互动。"炎黄子孙"自此成为中华民族的集体记忆。' },
  { id: 'tr-history-dongyi', category: 'history', title: '东夷人', summary: '6500 多年前的"山东人" — 东部沿海的史前文化先民，与海岱文明密切相关。', era: '约 BC 4500', imageKeyword: 'dongyi tribal culture shandong neolithic', fullContent: '东夷是华夏东部沿海及黄河下游地区众多部落的统称，以山东大汶口文化、龙山文化为代表。他们制作精美的黑陶和蛋壳陶，掌握了玉器加工技术。传说中太昊、少昊、舜、皋陶、伯益等都出自东夷。东夷与华夏经过长期战争与融合，最终成为中华文明的多元源头之一。' },
  { id: 'tr-history-miaoyao', category: 'history', title: '苗瑶人', summary: '5000 多年前的"两湖人" — 长江中游的史前族群，后部分南迁为苗瑶等民族。', era: '约 BC 3000', figure: '蚩尤', imageKeyword: 'miaoyao tribal yangtze river hunan', fullContent: '苗瑶先民活动于长江中游，以湖南、湖北为中心。涿鹿之战中蚩尤战败后，部分族人南迁至湘西、黔东南，形成后来的苗族；另一支沿东南方向迁徙，演变为瑶族、畲族等。他们在历史上多次起义反抗中原王朝，文化中保留了强烈的迁徙记忆与图腾崇拜。' },
  { id: 'tr-history-liangzhu', category: 'history', title: '良渚人', summary: '5000 多年前的"江南人" — 长江下游玉器文明，神徽与水利工程震惊世界。', era: '约 BC 3300-2300', imageKeyword: 'liangzhu jade culture ancient china', fullContent: '良渚文化是东亚最早的国家形态之一，以浙江余杭良渚遗址命名。其玉琮上的神人兽面纹是中国最早的"国家 logo"。良渚人修建了大型水利工程——由 11 条水坝组成的防洪系统，是中国最早的大型公共工程。神权与王权合一，玉器是身份等级的标志。' },
  { id: 'tr-history-hongshan', category: 'history', title: '红山人', summary: '5000 多年前的红山"老住户" — 西辽河流域玉龙女神庙，开启北方文明。', era: '约 BC 4700', imageKeyword: 'hongshan jade dragon neolithic culture', fullContent: '红山文化以辽西红山命名，出土了著名的玉龙、C 形龙和泥塑女神头像。其玉器制作精美，是中国龙文化的源头之一。红山人已经出现神权崇拜、祖先祭祀，玉龙可能是沟通天地神灵的礼器。玉猪龙、勾云形玉佩等器物，显示出北方文明与中原的平行发展。' },
  { id: 'tr-history-shimao', category: 'history', title: '石峁古城', summary: '4000 多年前的"石头王国" — 陕西神木发现的史前最大城址，皇权雏形。', era: '约 BC 2300-1800', imageKeyword: 'shimao stone fortress prehistoric china', fullContent: '石峁遗址位于陕西神木，是东亚乃至世界史前最大城址，面积约 425 万平方米。皇城台、宫城、内城、外城层层嵌套，防御体系严密。出土石雕人面像、鳄鱼骨板、口簧等，显示与中原龙山文化和北方草原文化的互动。石峁可能是中国第一个"国家"的雏形。' },
  { id: 'tr-history-yaoshunyu', category: 'history', title: '尧舜禹', summary: '传说中的上古帝王 — 禅让制与世袭制的交替，部落联盟向国家过渡。', era: '约 BC 2300', figure: '尧 / 舜 / 禹', imageKeyword: 'yao shun yu ancient chinese emperors', fullContent: '尧舜禹时代是禅让制的高峰：尧让位于舜，舜让位于禹。但禹传子启，世袭制取代禅让，中国第一个王朝"夏"由此诞生。鲧禹治水是这一时期的标志性事件——大禹"三过家门而不入"，疏导而非堵塞的治水理念，奠定了中原农业文明的基础。虞舜时期的"象刑"和"明刑弼教"是早期法治萌芽。' },
  { id: 'tr-history-xia', category: 'history', title: '夏朝', summary: '拥有"黑科技"的"内向"王朝 — 中国第一个王朝，二里头遗址揭示青铜文明。', era: 'BC 2070-1600', figure: '大禹 / 启', imageKeyword: 'xia dynasty erlitou bronze china', fullContent: '夏朝是中国史书记载的第一个王朝，大禹治水后传位于启，世袭制取代禅让制。二里头遗址可能是夏代都城，其绿松石龙形器、青铜爵等揭示了夏代的青铜文明。夏代已有历法（《夏小正》）、水利工程和早期国家机器。"内向"在于夏人较少对外扩张，主要治理中原水患与部落。' },
  { id: 'tr-history-shang', category: 'history', title: '商朝', summary: '打打杀杀的王朝 — 商汤伐桀、盘庚迁殷、妇好征羌，甲骨文与青铜器鼎盛。', era: 'BC 1600-1046', figure: '商汤 / 盘庚 / 妇好', imageKeyword: 'shang dynasty yinxu oracle bone bronze', fullContent: '商朝以殷商为代表，盘庚迁殷后稳定 270 余年。商代最大成就是甲骨文 — 刻在龟甲兽骨上的占卜记录，是中国已知最早的成熟文字。青铜器制作达到当时世界顶峰，司母戊鼎重 832 公斤。妇好是中国最早的女将军，率军征羌、土方、夷方。商纣王因暴政亡国，《封神榜》以此为蓝本。' },
  { id: 'tr-history-shu', category: 'history', title: '神秘的古蜀人', summary: '一群沉迷于和老祖宗沟通的人 — 三星堆、金沙遗址，出土青铜神树与面具。', era: '约 BC 1700-1200', imageKeyword: 'sanxingdui bronze mask ancient shu', fullContent: '古蜀文明以三星堆和金沙遗址为代表，与中原商周同期但独立发展。三星堆出土的青铜神树（高 3.96 米）、纵目面具、青铜立人像，工艺令人叹为观止。古蜀人祭祀太阳神、崇拜祖先，黄金面具、太阳神鸟金箔显示其独特信仰。这一文明突然消失，可能与洪水或战争有关。' },
  { id: 'tr-history-zhou', category: 'history', title: '周人', summary: '一群来自大西北的种田能手 — 周族崛起于渭水流域，农牧混合经济。', era: '约 BC 1100', figure: '古公亶父 / 季历', imageKeyword: 'zhou tribe qishan weishui china agriculture', fullContent: '周族起源于渭水流域的黄土高原，擅长农业。古公亶父（周太王）受薰育戎狄压迫，迁至岐山下的周原，建城邑、设官吏、改革习俗，奠定了周人崛起的根基。季历时期周人开始与商王朝合作征伐西戎。文王姬昌继位后，礼贤下士、积蓄力量，为武王伐纣做准备。' },
  { id: 'tr-history-xizhou', category: 'history', title: '西周', summary: '开始讲"礼"的时代 — 分封制、宗法制、礼乐文明奠定中华秩序。', era: 'BC 1046-771', figure: '周武王 / 周公', imageKeyword: 'western zhou dynasty bronze ritual vessel', fullContent: '公元前 1046 年，武王伐纣，牧野之战后建立西周。周公旦制礼作乐，建立了完整的宗法分封制：天子-诸侯-卿大夫-士层层分封，嫡长子继承为核心。周礼影响后世三千年，虽经战乱摧毁，核心精神始终延续。共和元年（BC 841）是中国确切纪年的开始。' },
  { id: 'tr-history-chunqiu', category: 'history', title: '春秋', summary: '"礼仪第一，争霸第二"的时代 — 周王室衰微，诸侯会盟争霸。', era: 'BC 770-476', figure: '孔子 / 老子', imageKeyword: 'spring autumn period chinese states ritual', fullContent: '公元前 770 年周平王东迁洛邑，东周开始。诸侯不再朝觐周王，形成齐桓公、晋文公、楚庄王等"春秋五霸"轮流坐庄的局面。诸侯通过会盟（如葵丘之盟）维持表面秩序，实则战争频仍。孔子修订《春秋》，老子著《道德经》，"礼乐崩坏"反而催生百家争鸣。' },
  { id: 'tr-history-zhanguo', category: 'history', title: '战国', summary: '"不是你死，就是我亡"的时代 — 七雄并立，变法图强。', era: 'BC 475-221', figure: '商鞅 / 苏秦', imageKeyword: 'warring states period qin shuihu', fullContent: '战国时期只剩齐、楚、燕、韩、赵、魏、秦七雄和少数小国。各国内部掀起变法浪潮：魏文侯用李悝、商鞅在秦变法最为彻底。秦以法家立国，军功爵制激发战力；齐设稷下学宫招揽百家；赵武灵王胡服骑射；魏、楚也各有改革。"合纵连横"的外交博弈与残酷战争交织，公元前 221 年秦灭六国终结乱世。' },
  { id: 'tr-history-qinren', category: 'history', title: '秦人', summary: '"一统天下"的竟然是一群养马人 — 秦族崛起于陇西，牧马立国。', era: '约 BC 900-221', figure: '非子 / 秦襄公', imageKeyword: 'qin people horse breeding longxi', fullContent: '秦人起源于今甘肃东南的陇西地区，始祖非子以养马有功被周孝王封于秦邑，成为周的附庸。秦襄公因护送周平王东迁有功，被封为诸侯。秦人长期被视为"西陲"戎狄，但他们通过与戎狄的军事对抗，锻炼出坚韧的战斗力。秦穆公任用百里奚，称霸西戎，为后世秦始皇统一六国奠定基础。' },
  { id: 'tr-history-qin', category: 'history', title: '秦朝', summary: '秦始皇的"大机器" — 书同文、车同轨、行同伦、法家治国。', era: 'BC 221-206', figure: '秦始皇 / 李斯', imageKeyword: 'qin dynasty terracotta warriors', fullContent: '公元前 221 年，秦王嬴政完成统一大业，建立中国第一个中央集权的多民族国家。秦始皇推行一系列影响深远的制度：书同文（小篆）、车同轨、统一度量衡、北击匈奴、修万里长城、南征百越、修灵渠、统一货币。中央设三公九卿，地方推行郡县制。法家思想治国的"大机器"高效但严苛，秦二世而亡仅 15 年，但奠定了中国两千年帝制的基本框架。' },
  { id: 'tr-history-han', category: 'history', title: '汉朝', summary: '"长寿"的汉王朝 — 文景之治、汉武盛世、独尊儒术。', era: 'BC 202-AD 220', figure: '刘邦 / 汉武帝', imageKeyword: 'han dynasty silk road changan', fullContent: '汉朝分西汉（前 202-9）与东汉（25-220），共 400 余年，是中国第一个"长寿"的大一统王朝。文景之治以黄老无为先，开创盛世；汉武帝"罢黜百家，独尊儒术"，北击匈奴凿空西域，张骞通使开辟丝绸之路，卫青霍去病封狼居胥。汉朝确立的儒家正统、外戚宦官制度、察举制等深刻影响后世。' },
  { id: 'tr-history-sanguo', category: 'history', title: '三国时期', summary: '不稳定的"三足鼎立" — 魏蜀吴三分天下，英雄与谋略的时代。', era: 'AD 220-280', figure: '曹操 / 诸葛亮', imageKeyword: 'three kingdoms period chinese', fullContent: '东汉末年黄巾起义、董卓乱政后，形成魏、蜀、吴三国鼎立局面。220 年曹丕代汉建魏，221 年刘备称帝建蜀，229 年孙权称帝建吴。三国仅 60 年，但英雄辈出：曹操的雄才、诸葛亮的智谋、周瑜的儒雅、关羽的忠义。这一时期佛教开始传入中国，文学上"建安七子"引领风骚。' },
  { id: 'tr-history-beichao', category: 'history', title: '五胡十六国与北朝', summary: '少数民族入主中原 — 匈奴、鲜卑、羯、氐、羌建立北方政权。', era: 'AD 304-589', imageKeyword: 'northern dynasties five barbars china', fullContent: '西晋末年八王之乱后，匈奴刘渊、羯族石勒、氐族苻健、羌族姚苌、鲜卑拓跋氏等"五胡"建立十余国，北方进入大分裂。前秦苻坚一度统一北方，但淝水之战败于东晋后瓦解。北魏孝文帝推行汉化改革——迁都洛阳、改汉姓、穿汉服、说汉话、与汉族通婚，推动民族大融合。这一时期佛教大盛，云冈、龙门石窟开凿。' },
  { id: 'tr-history-nanbeichao', category: 'history', title: '东晋与南朝', summary: '流水的皇帝，铁打的世家 — 门阀士族与皇权共治南方。', era: 'AD 317-589', imageKeyword: 'eastern jin southern dynasties china aristocracy', fullContent: '317 年司马睿南渡建康（今南京），建立东晋。晋宋齐梁陈五朝更迭，共 272 年，史称"南朝"。这一时期门阀士族（王、谢、袁、萧等）掌控政治与社会资源，"上品无寒门，下品无士族"。宋武帝刘裕代晋开启南朝，但皇权始终受制于世家大族。梁武帝萧衍崇佛，却因侯景之乱饿死台城——世家门阀的固化是南朝始终"流水的皇帝"的根因。' },
  { id: 'tr-history-sui', category: 'history', title: '隋朝', summary: '"来也匆匆，去也匆匆"的朝代 — 短暂但结束分裂，开皇之治。', era: 'AD 581-618', figure: '隋文帝 / 隋炀帝', imageKeyword: 'sui dynasty grand canal yangdi', fullContent: '隋朝仅 38 年，但影响深远。隋文帝杨坚结束南北朝分裂，开皇之治下府库充盈、刑政宽简，确立三省六部制、科举制雏形。隋炀帝杨广开通大运河、营建东都洛阳、三征高句丽，劳民伤财导致天下大乱。但大运河贯通南北，沟通了经济命脉，惠及唐宋。隋朝是中华文明从分裂走向统一的转折期。' },
  { id: 'tr-history-tang', category: 'history', title: '唐朝', summary: '自信、从容的朝代 — 贞观之治、开元盛世，开放包容的国际时代。', era: 'AD 618-907', figure: '唐太宗 / 武则天', imageKeyword: 'tang dynasty changan capital cosmopolitan', fullContent: '唐朝是中国历史上最自信、最国际化的时代。贞观之治（唐太宗）、开元盛世（唐玄宗）创造空前繁荣，长安城人口过百万，是当时世界最大的国际都市。科举制成熟，诗赋取士让寒门子弟有了上升通道。武则天是中国唯一的女皇帝，诗仙李白、诗圣杜甫记录盛世气象。安史之乱后唐朝由盛转衰，藩镇割据埋下五代十国的种子。' },
  { id: 'tr-history-wudai', category: 'history', title: '五代十国', summary: '千万不要穿越的朝代 — 短短 53 年五代更迭、十国分立。', era: 'AD 907-979', imageKeyword: 'five dynasties ten kingdoms chaos china', fullContent: '唐朝灭亡后，中国再次陷入大分裂。北方依次出现后梁、后唐、后晋、后汉、后周五个短命王朝，平均每个朝代不到 11 年；南方则有前蜀、后蜀、吴、南唐、吴越、闽、楚、南汉、南平、北汉等十国并存。这一时期武夫当国，节度使凭武力夺取政权，"天子"如走马灯。但乱世也孕育了统一，后周世宗柴荣改革为赵匡胤建立北宋奠定了基础。' },
  { id: 'tr-history-song', category: 'history', title: '宋朝', summary: '文科第一名，打仗不太行 — 商业繁荣、文化巅峰、武力疲弱。', era: 'AD 960-1279', figure: '赵匡胤 / 苏轼', imageKeyword: 'song dynasty hangzhou commerce invention', fullContent: '宋朝分为北宋（960-1127）与南宋（1127-1279），共 319 年。陈桥兵变赵匡胤黄袍加身，"杯酒释兵权"解决藩镇割据。宋朝"重文轻武"，科举扩招、士大夫政治达到顶峰。商业革命催生世界最早的纸币"交子"，活字印刷、指南针、火药在宋代广泛应用。苏轼、李清照、辛弃疾代表的宋词达到文学巅峰。但"靖康之耻"暴露军事疲弱，最终亡于蒙古铁骑。' },
  { id: 'tr-history-yuan', category: 'history', title: '元', summary: '草原战斗民族的天下 — 蒙古铁骑横扫欧亚，疆域空前。', era: 'AD 1271-1368', figure: '成吉思汗 / 忽必烈', imageKeyword: 'yuan dynasty mongol empire kublai khan', fullContent: '1206 年铁木真统一蒙古诸部，称成吉思汗。蒙古帝国在三代人手里扩张到欧亚大陆：灭西夏、灭金、灭大理、灭南宋。1271 年忽必烈定国号"大元"，1279 年崖山之战彻底灭宋。元朝是中国历史上第一个由少数民族建立的大一统王朝，行省制度影响深远。马可·波罗笔下的元大都（北京）是世界级都市。但民族压迫政策激化矛盾，不足百年亡于明初。' },
  { id: 'tr-history-yuanhou', category: 'history', title: '元之后的蒙古人', summary: '哪儿来的，回哪儿去了吗？ — 北元与鞑靼、瓦剌的分化。', era: 'AD 1368-17世纪', imageKeyword: 'northern yuan mongol khatagin tatars', fullContent: '1368 年明军攻陷大都，元顺帝北逃应昌，北元政权继续存在近 30 年，后分裂为鞑靼（东部蒙古）和瓦剌（西部蒙古）。瓦剌在 1449 年土木堡之变中俘虏明英宗，1500 年达延汗短暂统一蒙古。明嘉靖年间俺答汗与明朝达成"隆庆和议"，恢复边境贸易。清代科尔沁、准噶尔等蒙古部落或归附或被征服，最终纳入清朝版图。蒙古人在草原上以"盟旗制"延续，直至近现代。' },
  { id: 'tr-history-ming', category: 'history', title: '明朝', summary: '古怪皇帝一箩筐 — 朱元璋废丞相、郑和下西洋、崇祯自缢。', era: 'AD 1368-1644', figure: '朱元璋 / 张居正', imageKeyword: 'ming dynasty forbidden city zheng he', fullContent: '1368 年朱元璋建立明朝，废除丞相、设内阁，锦衣卫监控百官，洪武朝杀功臣十余万。朱棣靖难之役后迁都北京，派郑和七下西洋（1405-1433），最远抵达非洲东岸。明朝中后期皇帝多怠政（万历 28 年不上朝）、宦官专权（魏忠贤、刘瑾），东林党争消耗国力。张居正改革"一条鞭法"短暂续命，但万历三大征耗尽国库。1644 年李自成攻入北京，崇祯帝自缢煤山，明朝亡。' },
  { id: 'tr-history-nvzhen', category: 'history', title: '女真人入主中原', summary: '女真人从哪儿来？ — 建州女真崛起，建立后金→清。', era: 'AD 1616-1644', figure: '努尔哈赤', imageKeyword: 'jurchen manchu qing dynasty nuzhen', fullContent: '女真是满族的前身，起源于东北长白山地区，先后臣服于辽、金、明。明朝设建州卫管辖女真各部。1583 年努尔哈赤以"十三副遗甲"起兵，统一女真各部，1616 年建立后金，1636 年皇太极改国号为大清。女真（满洲）推行八旗制度，创满文，降服漠南蒙古。林丹汗败亡后，皇太极得以全力攻明。' },
  { id: 'tr-history-qing', category: 'history', title: '清朝', summary: '全面"打补丁"的王朝 — 康乾盛世后鸦片战争、戊戌变法、辛亥革命。', era: 'AD 1644-1912', figure: '康熙 / 雍正 / 乾隆', imageKeyword: 'qing dynasty forbidden city kangxi qianlong', fullContent: '1644 年清军入关，经康雍乾三朝达到"康乾盛世" — 疆域空前（1300 万平方公里）、人口破 4 亿、收复台湾、册封达赖班禅。但盛世之下危机四伏：文字狱钳制思想、八旗子弟腐化、闭关锁国。1840 年鸦片战争打开国门，此后太平天国、甲午战争、戊戌变法、辛亥革命接连不断。1912 年溥仪退位，中国两千多年帝制终结。清朝是中华帝国向近代民族国家转型的关键过渡期。' },
  // myth (3)
  { id: 'tr-myth-intro', category: 'myth', title: '引子：神话来了！', summary: '神话是远古先民对世界的好奇与想象，是中国最早的"故事"。', era: '亘古', imageKeyword: 'chinese mythology intro ancient', fullContent: '神话不是凭空捏造，而是远古先民对天地万物最原始的探索。从盘古开天到女娲造人，从大禹治水到夸父逐日，中国神话承载着中华文明最初的宇宙观与世界观。这些故事既是文学，也是历史，更是哲学。' },
  { id: 'tr-myth-hunyin', category: 'myth', title: '混沌说和阴阳说', summary: '混沌初开，鸡子化生——可可爱爱和奇奇怪怪的创世神话。', era: '上古', imageKeyword: 'chaos yinyang chinese creation myth', fullContent: '《三五历纪》记"天地混沌如鸡子，盘古生其中"——这是混沌说。另一支《淮南子》讲阴阳二气化生万物，太阳为阳，月亮为阴，阴阳交感化生四时五行。两种创世说并存，前者具体可爱，后者抽象深刻。' },
  { id: 'tr-myth-gongzhu', category: 'myth', title: '水神共工和火神祝融', summary: '水神与火神的争斗，撞断不周山引发大洪水。', era: '上古', imageKeyword: 'gonggong zhurong water fire god', fullContent: '共工是水神，司雨泽；祝融是火神，掌光明。两人大战于不周山，共工怒触不周山（撑天之柱），天倾西北，地不满东南，于是女娲炼五色石补天，斩龟足立四极。这场战争解释了中国的山川地势。' },
  { id: 'tr-myth-xihe', category: 'myth', title: '羲和浴日', summary: '太阳之母，十日轮流坐班车去上班——《山海经》里的太阳神话。', era: '上古', imageKeyword: 'xihe sun mother ten suns', fullContent: '《山海经》载：东海之外，甘水之间，有羲和之国，羲和者，帝俊之妻，生十日。十日是帝俊与羲和的儿子，每天轮流一个坐妈妈的车去天上值日。羲和是太阳之母，也是日落日出的掌控者。' },
  { id: 'tr-myth-sun', category: 'myth', title: '太阳大灾难', summary: '羿射九日 + 夸父逐日——天上十日并出，英雄射日与追日。', era: '上古', imageKeyword: 'houyi archer sun shooting kuafu', fullContent: '尧时十日并出，焦禾稼，杀草木，羿仰天控弦，射落九日，留下一日。另一则夸父逐日，巨人夸父追太阳，渴饮渭水、河水仍不足，最终渴死于途，杖化为邓林。两种英雄叙事并存：前者为民除害，后者追求光明。' },
  { id: 'tr-myth-moon', category: 'myth', title: '月亮的故事', summary: '沐月、奔月与修月——嫦娥、玉兔、吴刚伐桂的月亮神话群。', era: '上古 ~ 汉', imageKeyword: 'moon chang e jade rabbit wugang', fullContent: '嫦娥奔月因偷食后羿的不死药，飞升月宫，独守广寒。月中有玉兔捣药，吴刚伐桂树（桂树随砍随合），唐明皇游月宫见仙人素娥。三国徐整《五运历年纪》记月中有蛤蟆，佛教传入后蛤蟆变玉兔。月亮神话不断层累。' },
  { id: 'tr-myth-fengyu', category: 'myth', title: '风雨雷电神', summary: '复杂的自然神团队——风师飞廉、雨师屏翳、雷公电母各司其职。', era: '上古 ~ 宋', imageKeyword: 'wind rain thunder chinese gods feilian', fullContent: '风师飞廉（鹿身雀首），雨师屏翳（鸟首人形），雷公（人形持锤鼓），电母（闪电娘娘）。《周礼》十煇、二十雨，《历代神仙通鉴》系统化为风雨雷电四大神祇。雷公电母本是雷神配偶，宋元后渐成体系。' },
  { id: 'tr-myth-sijji', category: 'myth', title: '春夏秋冬四季神', summary: '四神分住东南西北，主宰四季轮转与万物生长。', era: '上古', imageKeyword: 'four seasons gods spring summer', fullContent: '《淮南子·天文训》载：东方木神句芒，南方火神祝融，西方金神蓐收，北方水神玄冥。中央土神后土。五行配五方五季，是上古宇宙观的核心框架。后世又演化出春神青帝、夏神赤帝、秋神白帝、冬神黑帝的神系。' },
  { id: 'tr-myth-he', category: 'myth', title: '河神', summary: '绝美洛神（宓妃）与暴躁河伯（冯夷）——黄河与洛水的守护神。', era: '上古 ~ 魏', imageKeyword: 'luo goddess hebo river god', fullContent: '洛神宓妃，伏羲之女，溺于洛水为神。曹植《洛神赋》"翩若惊鸿，婉若游龙"塑造了最动人的河神形象。河伯冯夷，黄河之神，《九歌·河伯》写其"与女游兮河之渚"。洛神柔情，河伯暴躁，两类河神并立于神话谱系。' },
  { id: 'tr-myth-shan', category: 'myth', title: '山神', summary: '山无大小，皆有神灵——山神崇拜与山岳祭祀。', era: '上古 ~ 当代', imageKeyword: 'mountain god shan shen chinese', fullContent: '《五藏山经》记华夏 451 座山，每山皆有山神。泰山神东岳大帝，嵩山神中岳，华山神西岳，衡山神南岳，恒山神北岳——五岳五帝。山神崇拜延续至今，乡野山神、土地神仍受祭祀。"山无大小，皆有神灵"。' },
  { id: 'tr-myth-hongshui', category: 'myth', title: '那场洪荒世界的大水', summary: '大禹治水——从共工怒触不周山到大禹疏导江河的治水史诗。', era: '上古', imageKeyword: 'dayu great flood control', fullContent: '共工怒触不周山→女娲补天→鲧（禹父）窃息壤治水失败被殛于羽山→禹继承父业，三过家门不入，改堵为疏，导河入海，平定九州水患。治水史诗是中国上古史的核心叙事，"大禹治水"成为中华民族精神的象征。' },
  { id: 'tr-myth-fuxi', category: 'myth', title: '大神伏羲', summary: '最优秀的创业者——画卦、造字、结网、教嫁娶的人文始祖。', era: '上古', imageKeyword: 'fuxi eight trigrams bagua', fullContent: '伏羲一画开天，创先天八卦（乾兑离震巽坎艮坤）。与女娲兄妹相婚繁衍人类，教会渔猎（结网）、畜牧（养牺牲）、婚配（制嫁娶）、文字（造书契）、音乐（作琴瑟）。"最优秀的创业者"——以零基础缔造文明基础。' },
  { id: 'tr-myth-shennong', category: 'myth', title: '神农', summary: '上古农学家和药学家——尝百草、创农耕、定医药的炎帝神农。', era: '上古', imageKeyword: 'shennong herbal medicine agriculture', fullContent: '神农尝百草，一日遇七十毒，最终因尝断肠草而亡。他教民耕种，制耒耜，立市廛，发明陶器，并以身试药写下《神农本草经》。神农是农业之神、医药之神，也是中华文明的奠基者之一。' },
  { id: 'tr-myth-huangdi', category: 'myth', title: '中央天帝黄帝', summary: '神界爱迪生——造车、造船、指南车、缫丝的发明家天帝。', era: '上古', imageKeyword: 'huangdi yellow emperor invention', fullContent: '黄帝姬姓，名轩辕。中央土德之帝，黄色为尊。"神界爱迪生"——造车（轩辕氏车）、造舟、造指南车、始煮盐、始养蚕缫丝、始作弓矢、始穿井。黄帝之妻嫘祖养蚕、仓颉造字、伶伦作乐律——黄帝时代是发明集群。' },
  { id: 'tr-myth-yandi', category: 'myth', title: '南方赤帝炎帝', summary: '与神农不同的炎帝——南方火德之帝，主夏与南方。', era: '上古', imageKeyword: 'yandi flame emperor south', fullContent: '《淮南子》《礼记》等典籍中有两个炎帝：神农氏炎帝与南方赤帝炎帝。赤帝为五行神之一，"南方赤帝，火德之神，主夏与南方"。后世将神农与赤帝合二为一，但在早期神话中他们是不同的神祇。' },
  { id: 'tr-myth-huangzhanzheng', category: 'myth', title: '黄帝的战争', summary: '黄帝战蚩尤、炎帝——涿鹿之战的传说与战神谱系。', era: '上古', imageKeyword: 'huangdi chiyou war zhuolu', fullContent: '黄帝先战炎帝于阪泉，三战而胜；再战蚩尤于涿鹿。蚩尤铜头铁额，刀枪不入，能呼风唤雨。黄帝造指南车辨方向，得九天玄女授兵书，最终擒杀蚩尤。战神刑天、夸父、蚩尤并立，"黄帝的战争"是华夏文明奠基之战。' },
  { id: 'tr-myth-shaohao', category: 'myth', title: '西方白帝少昊', summary: '少昊的鸟王国——以鸟为图腾的西方金德之帝。', era: '上古', imageKeyword: 'shaohao white emperor bird', fullContent: '少昊名挚，金天氏。西方白帝，五行属金。少昊以鸟名官：凤鸟氏为历正，玄鸟氏为司分，伯赵氏为司至，青鸟氏为司启，丹鸟氏为司闭。少昊国是一个鸟的王国，每个官职都以鸟命名，是中国最早的"图腾官制"。' },
  { id: 'tr-myth-zhuansu', category: 'myth', title: '北方黑帝颛顼', summary: '颛顼的"绝地天通"——断绝天地通路的宗教改革。', era: '上古', imageKeyword: 'zhuanxu black emperor religion reform', fullContent: '颛顼高阳氏，北方水德之帝。最重要的神话事件是"绝地天通"——命重（南正）司天以属神，命黎（火正）司地以属民，断绝民间与天神的直接通路，确立官方祀神制度。这是一次重大的宗教改革，重塑了上古神权秩序。' },
  { id: 'tr-myth-diku', category: 'myth', title: '帝喾', summary: '最后的大神——五帝之末，殷商始祖帝喾的传说。', era: '上古', imageKeyword: 'diku emperor ku high ancestor', fullContent: '帝喾高辛氏，五帝之末。"最后的大神"——五帝时代至此结束。帝喾有四子：挚、契（殷商始祖）、尧、弃（周始祖）。帝喾以德治天下，明察秋毫，"顺天之义，知民之急"。殷商人以帝喾为始祖，地位极高。' },
  { id: 'tr-myth-wangmu', category: 'myth', title: '昆仑山西王母', summary: '王母娘娘最早是个丑八怪——《山海经》原始西王母形象。', era: '上古 ~ 汉', imageKeyword: 'queen mother kunlun wangmu', fullContent: '《山海经》载西王母"其状如人，豹尾虎齿，善啸，蓬发戴胜"——完全是位半人半兽的女神，与后世雍容华贵的王母娘娘反差极大。战国后西王母逐渐人化、神化，到《汉武故事》成为掌不死药的吉神，再到《穆天子传》与周穆王瑶池相会。' },
  { id: 'tr-myth-yuhuang', category: 'myth', title: '玉皇大帝是个什么神', summary: '玉帝源自上古天帝崇拜与民间信仰融合，宋代定型为天界最高神。', era: '上古 ~ 宋', imageKeyword: 'jade emperor yuhuang tian', fullContent: '玉皇大帝不是一开始就是天界最高神。先秦有"昊天上帝"，汉代有"太一神"，唐代才出现"玉皇"称号。宋真宗大中祥符八年（1015）尊玉皇为"太上开天执符御历含真体道玉皇大天帝"——玉帝正式定型为天界最高神。"接地气的神话"——本土与道教融合的产物。' },
  { id: 'tr-myth-minshen', category: 'myth', title: '民间的神', summary: '人与神的另一种沟通——城隍、土地、门神、灶神等民间信仰。', era: '汉 ~ 当代', imageKeyword: 'chenghuang tudi folk god', fullContent: '城隍神是城市的守护神（始于汉代祭祀城池水庸）；土地神是乡村的守护者（俗称"土地公"）；门神秦叔宝、尉迟恭；灶神（灶王爷）腊月二十三上天汇报一家善恶。民间神是人与神沟通的另一种方式，是官方祀典之外的活态信仰。' },
  { id: 'tr-myth-jiashen', category: 'myth', title: '家家户户里的神', summary: '有神陪着我们每一家人——门神、灶神、井神、厕神、紫姑等。', era: '汉 ~ 当代', imageKeyword: 'door god kitchen god zigu', fullContent: '一家之中，神无处不在：门口门神（秦叔宝、尉迟恭），厨房灶神（灶王爷），水井井神，茅厕厕神紫姑（元宵节迎紫姑），床神床婆床公。"有神陪着我们每一家人"——中国家庭空间是神界的微缩，从门到床各有主。' },
  { id: 'tr-myth-long', category: 'myth', title: '龙的家族', summary: '龙也分三六九等——上古龙神到帝王象征的演化。', era: '上古 ~ 当代', imageKeyword: 'chinese dragon long mythology', fullContent: '龙从上古的图腾神（伏羲、黄帝、炎帝皆乘龙）演化到帝王象征（皇帝是真龙天子），再到佛教的龙王（掌四海）。龙分三六九等：应龙（有翼）、蛟龙、虬龙、螭龙、蟠龙各司其职。"龙的传人"是从龙崇拜延续至今的民族认同。' },
  { id: 'tr-myth-long9zi', category: 'myth', title: '龙生九子', summary: '九个龙子各有地盘——赑屃、椒图、嘲风、蒲牢、狻猊等。', era: '上古 ~ 明', imageKeyword: 'nine sons of dragon long9zi', fullContent: '明代李东阳《怀麓堂集》：龙生九子各有所好。一曰赑屃（霸下），好负重，碑下龟趺；二曰椒图，好闭，铺首衔环；三曰嘲风，好险，殿角走兽；四曰蒲牢，好鸣，钟上钮；五曰狻猊，好坐，佛座；六曰霸下（赑屃）；七曰睚眦，好杀，刀柄龙吞口；八曰负屃，好文，碑侧；九曰鸱吻（螭吻），好吞，殿脊。' },
  { id: 'tr-myth-ruishou', category: 'myth', title: '神圣祥瑞之兽', summary: '万事都要讲究个吉祥如意——凤、麒麟、貔貅、独角兽。', era: '上古 ~ 当代', imageKeyword: 'auspicious beast feng qilin pixiu', fullContent: '凤为百鸟之王，雄凤雌凰；麒麟（麋身牛尾龙鳞）象征仁德；貔貅招财辟邪；独角兽（獬豸）辨是非；玄武（龟蛇）北方之精；白虎西方之灵；青龙东方之神；朱雀南方之瑞。"万事都要讲究个吉祥如意"——瑞兽信仰融入日常。' },
  { id: 'tr-myth-wanwu', category: 'myth', title: '万物皆有灵', summary: '神仙？妖怪？——山精水怪、花妖狐魅、精魅妖灵的万物有灵观。', era: '上古 ~ 当代', imageKeyword: 'spirit of all things fox spirit', fullContent: '《搜神记》《聊斋志异》《酉阳杂俎》记山精、水怪、花妖、狐魅——万物皆有灵。狐仙（狐精修炼成仙）、聂小倩、画皮、青蛇白蛇。中国万有灵观不只在神祇，更在精魅——精魅与神祇共同构成了完整的精灵世界。"神仙？妖怪？"其实并无绝对界限。' },
  // philosophy (4){ id: 'tr-phil-intro', category: 'philosophy', title: '引子：哲学从这里开始', summary: '哲学是对世界的好奇与追问——中国人从哪儿来，到哪里去，活着为什么。', era: '春秋', imageKeyword: 'chinese philosophy intro ancient', fullContent: '哲学不是玄学，而是对根本问题的追问。西方哲学始于惊讶（泰勒斯），中国哲学始于忧患（孔子作《春秋》因"忧"。追问"我从哪里来"，"如何活着"，"怎样才算有意义"——这些是中国哲学的起点。' },
  { id: 'tr-phil-kongzi', category: 'philosophy', title: '孔子的"仁"和"礼"', summary: '仁是内在的德性，礼是外在的规范——"克己复礼为仁"。', era: 'BC 551-479', imageKeyword: 'confucius ren li analects', fullContent: '孔子名丘，字仲尼，春秋鲁国人。仁者爱人——"仁"是内在的德性，发自内心地尊重他人；"礼"是外在的规范，包括周礼、仪节、伦常。"克己复礼为仁"——克制自己回归礼，才能实现仁。《论语》二十篇五千余言，是儒家根本经典。' },
  { id: 'tr-phil-zisi', category: 'philosophy', title: '子思和《中庸》', summary: '中庸是儒家的人生"说明书"——不偏不倚，过犹不及。', era: 'BC 481-402', imageKeyword: 'zisi zhongyong doctrine mean', fullContent: '子思名伋，孔鲤之子，孔子之孙。曾子受学于孔子，子思受学于曾子，传于孟子。子思作《中庸》，原是《礼记》中一篇，宋儒把它与《大学》《论语》《孟子》并为四书。中庸不是平庸，而是"致中和"的极高境界。' },
  { id: 'tr-phil-mengzi', category: 'philosophy', title: '孟子的"四端"说', summary: '仁义礼智，非由外铄我也，我固有之——"仁"需要勤"浇水"！', era: 'BC 372-289', imageKeyword: 'mencius four sprouts siduan', fullContent: '孟子名轲，邹国人，孔子之孙子思的再传弟子。性善论：人皆有"四端"——恻隐之心（仁之端）、羞恶之心（义之端）、辞让之心（礼之端）、是非之心（智之端）。这四端如同四颗种子，需要勤"浇水"（修养）才能长成仁义礼智四种德性。' },
  { id: 'tr-phil-xunzi', category: 'philosophy', title: '荀子和"人性恶"', summary: '人之性恶，其善者伪也——礼是一种红绿灯。', era: 'BC 313-238', imageKeyword: 'xunzi human nature evil', fullContent: '荀子名况，赵国人。与孟子性善论相反，荀子主张性恶论——"人之性恶，其善者伪也"（伪=人为）。但这不意味人不可救——礼法是规范人的"红绿灯"，通过后天教化（伪）让人向善。荀子是礼法思想的源头，也培养了韩非子、李斯两位法家代表。' },
  { id: 'tr-phil-ruwu', category: 'philosophy', title: '能文能武的儒家', summary: '儒士也有武力值——文武双全的早期儒家。', era: '春秋 ~ 汉', imageKeyword: 'ru jia wen wu confucian warrior', fullContent: '先秦儒家不只是文弱书生。孔子本人会驾车、习射御，"六艺"包含礼、乐、射、御、书、数。孟子也讲"善战者服上刑"。后世文武分途，宋明以后儒家才逐渐以文为主。能文能武——才是儒家的完整形象。' },
  { id: 'tr-phil-laozi', category: 'philosophy', title: '老子和"无为"', summary: '道可道，非常道——"不分别"的智慧。', era: 'BC 571-471', imageKeyword: 'laozi dao wuwei taoism', fullContent: '老子姓李名耳，字聃（伯阳），春秋楚国苦县人。《道德经》五千言——"道可道，非常道；名可名，非常名"。无为不是什么都不做，而是"不妄为"，顺应道的规律。"不分别"——不对立、不执着、超越二元对立的智慧，是道家根本。' },
  { id: 'tr-phil-zhuangzi', category: 'philosophy', title: '庄子和"蝴蝶"', summary: '庄周梦为蝴蝶——不要绑住你自己！', era: 'BC 369-286', imageKeyword: 'zhuangzi butterfly freedom', fullContent: '庄子名周，宋国蒙人。《庄子》内七篇外十五篇杂篇。"庄周梦为胡蝶，栩栩然胡蝶也，不知周也。俄然觉，则蘧蘧然周也。不知周之梦为胡蝶与，胡蝶之梦为周与？"——庄周与蝴蝶的界限是确定的？齐物、逍遥——不要绑住你对世界的固定看法。' },
  { id: 'tr-phil-yangzhu', category: 'philosophy', title: '杨朱和"贵我"', summary: '拔一毛而利天下，不为也——反"道德绑架"的先锋。', era: 'BC 440-360', imageKeyword: 'yangzhu selfish weiwo', fullContent: '杨朱魏国人，先秦诸子中争议最大者之一。"贵己"（贵我）——"拔一毛而利天下，不为也"，天下大利也不换取一根毫毛。杨朱不是自私自利，而是反对以"利天下"为名的道德绑架——个人价值不能为抽象"天下"所吞没。先秦有"天下之言不归杨则归墨"。' },
  { id: 'tr-phil-mozi', category: 'philosophy', title: '墨子和"兼爱非攻"', summary: '兼相爱，交相利——永远没有战争，能实现吗？', era: 'BC 470-391', imageKeyword: 'mozi universal love feigong', fullContent: '墨子名翟，鲁国人（一说宋国人）。兼爱（爱一切人，不分亲疏远近）、非攻（反对侵略战争）、尚贤（不分贵贱唯才是举）、节用（反对奢侈）、明鬼（相信鬼神赏善罚恶）。墨家是先秦与儒家并称的"显学"，弟子严守纪律，身体力行，墨子本人身体力行"兼爱"。' },
  { id: 'tr-phil-sunzi', category: 'philosophy', title: '孙子的"战和不战"', summary: '不战而屈人之兵，善之善者——受欺负时，要不要反抗？', era: 'BC 545-470', imageKeyword: 'sunzi art of war philosophy', fullContent: '孙子名武，字长卿，齐国人。《孙子兵法》十三篇。"兵者，国之大事，死生之地，存亡之道，不可不察"。最上策是"不战而屈人之兵，善之善者"。孙子不仅是兵家，更是哲学——"知彼知己，百战不殆""兵无常势，水无常形"。受欺负时，要么忍，要么战，要么智取——三种选择的辩证法。' },
  { id: 'tr-phil-hanfei', category: 'philosophy', title: '韩非子和"法"', summary: '法、术、势三者合一——别整那些没用的，用"法"！', era: 'BC 280-233', imageKeyword: 'hanfei legalism fa shu shi', fullContent: '韩非韩国公子，师从荀子。《韩非子》五十五篇。法家集大成者——法（成文法令）、术（君王驭臣手段）、势（君王绝对权威）三者合一。"别整那些没用的"——儒家讲仁义道德，道家讲无为，韩非子直接用法家治国——秦用之统一天下。法家是冰冷的政治哲学。' },
  { id: 'tr-phil-gongsunlong', category: 'philosophy', title: '公孙龙的"白马非马"', summary: '白马非马——脑子爱绕弯的名家诡辩论。', era: 'BC 320-250', imageKeyword: 'gongsunlong white horse paradox', fullContent: '公孙龙赵国人，名家代表。"白马非马"——白马是"白马"（白色+马形），马是"马"（泛指），二者是"异"而非"同"。诡辩？逻辑学？公孙龙是中国最早的逻辑学家，研究"概念""指称""异同"，是中国先秦哲学中被忽视的逻辑学遗产。' },
  { id: 'tr-phil-guanzi', category: 'philosophy', title: '《管子》的"气论"', summary: '凡物之精，此则为生——"燃起来"是怎么回事？', era: 'BC 720-645', imageKeyword: 'guanzi qi vital energy', fullContent: '《管子》托名管仲（齐桓公相），实际是战国至汉初稷下学宫的论文集。"气论"——精也者，气之精者也，凡物之精此则为生。"气"是构成万物的精微物质，是中国哲学的核心概念。人的生死、物的变化都是"气"的聚散——"燃起来"就是气充盈、阳气上升。' },
  { id: 'tr-phil-yijing', category: 'philosophy', title: '《易经》中的"变化"', summary: '穷则变，变则通，通则久——古人如何"掐指一算"？', era: 'BC 1100-500', imageKeyword: 'yijing i ching change', fullContent: '《易经》包括《周易》本经（卦辞爻辞）与《易传》（十翼）。六十四卦三百八十四爻——阴阳两种符号排列组合。"穷则变，变则通，通则久"——变化是宇宙根本规律。"掐指一算"通过卦象推演未来，是基于"感应""类比"的思维模型，是"象数学"。"一阴一阳之谓道"。' },
  { id: 'tr-phil-yinyangjia', category: 'philosophy', title: '阴阳家与"五行"理论', summary: '金木水火土相生相克——战国时的高精尖人才。', era: 'BC 300-200', imageKeyword: 'yinyang five elements wuxing', fullContent: '阴阳家以邹衍为代表，战国齐国人。"五德终始说"——金木水火土五行相生（木生火，火生土，土生金，金生水，水生木）、相克（水克火，火克金，金克木，木克土，土克水），用五行解释朝代更替与历史循环。"高精尖人才"——把天文、地理、历法、政治融为一体的智库。' },
  { id: 'tr-phil-guiguzi', category: 'philosophy', title: '鬼谷子的"谋略"', summary: '捭阖之道——想要赢，得会"谋"！', era: 'BC 400-300', imageKeyword: 'guiguzi strategy persuasion', fullContent: '鬼谷子王诩，纵横家鼻祖，传说苏秦、张仪皆出其门。《鬼谷子》十三篇——"捭阖"（开合）、"反应"（回应与反应）、"内揵"（进言之道）、"抵巇"（弥补缝隙）。谋略不是阴谋，而是对心理、人性、形势的洞察。"想要赢，得会"谋""——智慧博弈。' },
  { id: 'tr-phil-dongzhongshu', category: 'philosophy', title: '董仲舒的"天人感应"论', summary: '天意与人事相通——太阳黑子出现了？那是上天的神秘力量！', era: 'BC 179-104', imageKeyword: 'dongzhongshu tian ren感应', fullContent: '董仲舒广川人，西汉大儒。汉武帝"罢黜百家，独尊儒术"实际由董仲舒推动。"天人感应"——天意通过灾异、祥瑞与人事相通。君主无道，天降灾异；君主有德，天降祥瑞。这是儒家的神学化，也是中国式"自然法"的雏形。谶纬神学在此基础上发展。' },
  { id: 'tr-phil-xuanxue', category: 'philosophy', title: '魏晋玄学', summary: '天地万物皆以无为本——"逆反期"哲学。', era: 'AD 220-420', imageKeyword: 'wei jin xuanxue metaphysics', fullContent: '魏晋玄学是对两汉僵化经学的"逆反期"——挣脱名教束缚，回到《老子》《庄子》《周易》（"三玄"），探讨有无、本末、言意关系。何晏、王弼"贵无"，裴頠"崇有"，郭象"独化"。玄学家以清谈为风尚，服食养生，任情恣性，是一次精神的解放运动。' },
  { id: 'tr-phil-heyan', category: 'philosophy', title: '何晏的"贵无论"', summary: '天地万物皆以无为本——别小看"无"，它才是世界的本质！', era: 'AD 195-249', imageKeyword: 'heyan guiwu nothingness', fullContent: '何晏南阳人，魏晋玄学贵无派代表。"天地万物皆以无为本"——"无"不是虚无，而是超越具体存在的本体。没有"无"，"有"无法存在；没有"母"，"子"无法产生。"别小看"无""——空无才是世界的本质。王弼继承并发展了何晏的贵无论。' },
  { id: 'tr-phil-wangbi', category: 'philosophy', title: '王弼的"得意忘象"', summary: '言者所以在意，得意而忘言——不要教条，要本质！', era: 'AD 226-249', imageKeyword: 'wangbi de yi wang xiang', fullContent: '王弼山阳人，魏晋玄学天才，24岁去世。注《老子》《周易》——"得意在忘象，得象在忘言"。"得意忘象"——真正领悟了义理，连卦象、言辞都可以忘掉。这是中国式的"现象学"——超越具体形式，直达本质。"不要教条，要本质"——经典是桥梁，不是目的地。' },
  { id: 'tr-phil-zhulinqixian', category: 'philosophy', title: '竹林七贤"越名教而任自然"', summary: '不要虚伪，要自由——嵇康阮籍山涛向秀刘伶阮咸王戎。', era: 'AD 220-280', imageKeyword: 'zhulin qixian seven sages bamboo grove', fullContent: '魏晋竹林七贤：嵇康、阮籍、山涛、向秀、刘伶、阮咸、王戎。"越名教而任自然"——挣脱儒家伦理束缚，任由自然本性流露。嵇康《与山巨源绝交书》嘲讽礼教；阮籍《咏怀诗》沉痛难言；刘伶《酒德颂》唯酒是务。这是中国历史上最有个性的文人集团——"不要虚伪，要自由"。' },
  { id: 'tr-phil-peiwei', category: 'philosophy', title: '裴頠的"崇有论"', summary: '至无是无有——"努力"是一种羞耻吗？', era: 'AD 267-300', imageKeyword: 'peiwei chongyou being primacy', fullContent: '裴頠河东人，西晋哲学家，著《崇有论》。"至无是无有"——如果绝对的"无"是真的"无"，那它就是虚无本身不存在；只有具体的"有"才是真实的。"崇有"反对何晏王弼"贵无"——不是空无是世界本原，而是具体的事物（自生而有）才是本体。"努力"有意义——存在先于本质。' },
  { id: 'tr-phil-foxue', category: 'philosophy', title: '佛学的传入', summary: '万法皆空——万事万物都是"心念一动"的显现。', era: 'AD 67 ~', imageKeyword: 'buddhism introduction china', fullContent: '佛教汉哀帝元寿元年（公元前2年）经西域传入中原，正式记载东汉永平年间（公元67年）白马寺。"万法皆空""诸行无常""诸法无我""涅槃寂静"——佛学四大真理。万事万物都是"心念一动"的显现，"色即是空，空即是色"。佛教哲学深刻改变了中国思想史。' },
  { id: 'tr-phil-wuzhi', category: 'philosophy', title: '佛学与"我执"', summary: '烦恼的根源——我执是痛苦的根。', era: 'AD 100 ~', imageKeyword: 'buddhism atman ego illusion', fullContent: '"我执"（梵文 atman-graha）——执着于"我"和"我所"。认为有一个独立不变的"自我"，执着于自己的身体、感受、思想、观念、财产。"我执"是痛苦的根源（"诸苦由贪嗔痴"）。破除我执的方法是"无我"（anatta）——认识到没有一个永恒的"我"，万物无常。这是佛学的核心解脱论。' },
  { id: 'tr-phil-zhoudunyi', category: 'philosophy', title: '周敦颐的"太极图说"', summary: '无极而太极——有困惑？自然万物会给你答案！', era: 'AD 1017-1073', imageKeyword: 'zhou dunyi taijitu neo confucian', fullContent: '周敦颐北宋理学开山祖，道州人。《太极图说》："无极而太极。太极动而生阳，动极而静，静而生阴……二气交感，化生万物……万物生生，而变化无穷焉。"融合《周易》《老子》《中庸》，是宋明理学的真正起点。"有困惑？自然万物会给你答案"——格物致知。' },
  { id: 'tr-phil-zhangzai', category: 'philosophy', title: '张载的"气本论"', summary: '太和所谓道——我们都是"气"！', era: 'AD 1020-1077', imageKeyword: 'zhangzai qi vital force', fullContent: '张载北宋"关学"宗师，陕西眉县横渠镇人。"太虚无形，气之本体"——气是宇宙根本。"太和所谓道"——气的和谐状态就是道。"为天地立心，为生民立命，为往圣继绝学，为万世开太平"——横渠四句。张载"气本论"是宋明理学中与程朱"理本论"并立的另一极。"我们都是气"。' },
  { id: 'tr-phil-ercheng', category: 'philosophy', title: '程颢、程颐的"天理"说', summary: '天理是宇宙根本，人为什么要"仁"？原因在宇宙里！', era: 'AD 1032-1085, 1033-1107', imageKeyword: 'cheng hao cheng yi tianli heaven principle', fullContent: '程颢（明道）、程颐（伊川）兄弟，北宋理学奠基者。"天理"——宇宙的根本规律和道德的根源。人为什么要"仁"？"仁"不是外在教条，而是天理在人性中的体现。"存天理，灭人欲"——保留天理、克制私欲。"饿死事小，失节事大"——伦理至上。二程理学由朱熹集大成。' },
  { id: 'tr-phil-zhuxi', category: 'philosophy', title: '朱熹的"性即理"', summary: '性者，心之所具之理——你和一朵小花，有共通的道理！', era: 'AD 1130-1200', imageKeyword: 'zhuxi zhu xi neo confucianism', fullContent: '朱熹南宋理学集大成者，徽州婺源人。"性即理"——人的本性就是宇宙之理在人身上的具体体现。理在物为"物理"，理在人为"性理"。"格物致知"——穷究事物之理。"存天理，灭人欲"——朱熹把二程理学系统化，编注《四书章句集注》，成为元明清七百年科举标准。"你和一朵小花有共通的道理"——万物一理。' },
  { id: 'tr-phil-wangyangming', category: 'philosophy', title: '王阳明的"心学"', summary: '心即理，知行合一——如何面对人生？这是一场心的"试炼"！', era: 'AD 1472-1529', imageKeyword: 'wang yangming xinxue mind learning', fullContent: '王守仁，世称阳明先生，浙江余姚人，明代心学集大成者。"心即理"——天理不在外物，而在吾心；"知行合一"——知而不行即是未知；"致良知"——人人都有的内在道德判断。"破山中贼易，破心中贼难"——外贼易除，内贼难破。"如何面对人生？这是一场心的"试炼""——阳明心学是中国哲学的高峰，至今影响东亚。' },
  // script (3)
{ id: 'tr-script-intro', category: 'script', title: '引子：文字的诞生', summary: '文字的诞生是人类文明跃迁的标志——从口耳相传到刻写传世。', era: '亘古', imageKeyword: 'invention of writing chinese characters', fullContent: '文字的诞生使人类摆脱了时空限制——口耳相传会被遗忘，但刻写的文字可以传之千古。从结绳记事到图画文字，从甲骨刻辞到今日电子文本，每一次媒介革命都是人类文明的跃迁。中国汉字是世界上唯一延续三千年的表意文字系统，是活的文化遗产。' },
  { id: 'tr-script-cangjie', category: 'script', title: '那个造字的人仓颉', summary: '仓颉是个文字整理专家——传说造字天雨粟鬼夜哭。', era: '上古', imageKeyword: 'cangjie chinese character creator', fullContent: '仓颉黄帝史官，相传造字。《淮南子》记仓颉造字"天雨粟，鬼夜哭"——天地震动，连鬼神都惊动了。仓颉可能不是一个人的发明，而是上古文字整理者的代表——他搜集、整理、规范了黄帝时代已有的图画符号，使之系统化。' },
  { id: 'tr-script-pictograph', category: 'script', title: '汉字的前身是图画', summary: '我们的老祖宗都是灵魂画手——图画文字到表意符号。', era: 'BC 5000 ~', imageKeyword: 'pictograph chinese origin', fullContent: '半坡陶符（BC 5000 前后）、大汶口陶文（BC 2500 前后）是最早的图画文字。河南贾湖刻符、陕西半坡陶符都是汉字的远祖。这些"灵魂画手"画的不是写实，而是表意的符号——日画成○、月画成🌙、山画成⿱。图画文字演变为表意符号，是汉字的源头。' },
  { id: 'tr-script-jinwen', category: 'script', title: '金文', summary: '铸在青铜器上的国家大事——钟鼎文字记录商周礼制。', era: '商 ~ 周', imageKeyword: 'jinwen bronze inscription', fullContent: '金文又称钟鼎文，是铸刻在青铜器上的文字。商代晚期出现，西周达到鼎盛——毛公鼎铭文 497 字，是已知最长的金文。金文记录周王诰命、贵族祭祀、征伐盟誓，是研究先秦史的第一手资料。"铸在青铜器上的国家大事"——文字、礼器、政治三者合一。' },
  { id: 'tr-script-zhuanshu', category: 'script', title: '篆书', summary: '被秦始皇统一的文字——小篆是中国第一次书同文。', era: '秦', imageKeyword: 'zhuanshu seal script qin', fullContent: '秦统一六国（前 221）后，丞相李斯奏请"书同文"——以秦国文字为基础，整理出小篆，作为全国标准字体。小篆线条圆转、结构对称、笔画规范，是中国文字的第一次标准化。泰山、琅琊、会稽刻石都是李斯所书小篆。篆书是连接古文字与今文字的桥梁。' },
  { id: 'tr-script-lishu', category: 'script', title: '隶书', summary: '文字终于简单起来——隶变是汉字最大的一次结构简化。', era: '汉', imageKeyword: 'lishu clerical script han', fullContent: '隶书始于秦代，程邈整理，汉代成熟。隶变（篆书变隶书）是汉字最剧烈的一次简化——象形线条解体为点画波磔，结构从圆转方正。波磔（捺笔）是隶书的标志性笔画。隶书使书写效率大幅提升，为后来的楷书奠定基础。"文字终于简单起来"。' },
  { id: 'tr-script-wenfang', category: 'script', title: '文房四宝：笔墨纸砚', summary: '古人写字必须得有套趁手的工具——笔墨纸砚的进化史。', era: '汉 ~ 清', imageKeyword: 'wenfang sibao brush ink paper', fullContent: '笔墨纸砚是古人书写工具的四件套。笔——蒙恬改良毛笔；墨——汉代松烟墨，宋代油烟墨；纸——东汉蔡伦造纸术（其实西汉已有）；砚——从研石到端砚、歙砚、洮砚、澄泥砚。四大名砚中端砚最贵。工具的进化直接塑造了书写艺术。' },
  { id: 'tr-script-shuowen', category: 'script', title: '说文解字', summary: '许慎和他的汉语大字典——540 部首9353 字。', era: '东汉', imageKeyword: 'shuowen jiezi xu shen', fullContent: '许慎东汉汝南人，著《说文解字》十四篇，收字 9353 个（含重文 1163 个），按 540 部首编排，是中国第一部系统分析字形、考究字源的字典。许慎提出"六书"理论——象形、指事、会意、形声、转注、假借，成为后世汉字学的根基。' },
  { id: 'tr-script-xiangxing', category: 'script', title: '象形字', summary: '造字最开始是照葫芦画瓢——日月山水皆象形。', era: '商 ~', imageKeyword: 'xiangxing pictographic character', fullContent: '象形是六书之首——直接描绘事物形状。日画成○带一点（实为太阳之形）；月画成🌙（月牙形）；山画成⿱（三峰）；水画成氵（流水）；木画成本（树木）。象形字是汉字的根基，约占汉字总数 4%，但它是会意、形声等造字法的基础。' },
  { id: 'tr-script-zhishi', category: 'script', title: '指事字', summary: '考验想象力的时候到了——上下一二三等抽象符号。', era: '商 ~', imageKeyword: 'zhishi ideographic character', fullContent: '指事字用抽象符号表义。一（上）、二（两横）、三（三横）——纯指事字；上（点在横上）、下（点在横下）、本（木下加一横表根）、末（木上加一横表梢）——在象形字基础上加指示符号。指事字解决象形无法表达抽象概念的问题，约占汉字 1%。' },
  { id: 'tr-script-huiyi', category: 'script', title: '会意字', summary: '会不同汉字的意——休明林等合体字。', era: '商 ~', imageKeyword: 'huiyi associative compound', fullContent: '会意字合并两个或多个字的意。休（人+木，人靠在树下休息）、明（日+月，日月交辉）、林（双木成林）、森（三木成森）、信（人+言，说话算数）、安（女在屋下，安全）。会意字比象形字更灵活，约占汉字 13%，如武（止+戈，止戈为武）。' },
  { id: 'tr-script-xingsheng', category: 'script', title: '形声字', summary: '香火最旺的造字法——形旁表义声旁表音。', era: '商 ~ 当代', imageKeyword: 'xingsheng phono semantic', fullContent: '形声字由形旁（表义）+ 声旁（表音）组成。形旁如氵（水）、木（火）、讠（言）、扌（手）、艹（草）；声旁如青、请、清、情、精——都含"青"音。形声字占现代汉字 80% 以上，是最"香火最旺"的造字法。它解决了汉字既要表义又要表音的需求。' },
  { id: 'tr-script-zhuanzujie', category: 'script', title: '转注与假借', summary: '两种用字方法——不造新字也能表达新义。', era: '先秦', imageKeyword: 'zhuanzhu mutual loan', fullContent: '转注——同义或近义字互相解释，如考/老、老/考（同源字）；假借——借用已有字表新义，如"我"本是兵器名，借用作第一人称；"来"本是麦名，借用作"来去"的来。转注与假借不造新字，仅靠用法扩展字义，是汉字"经济性"的体现。' },
  { id: 'tr-script-zili', category: 'script', title: '字理识字', summary: '怎么把一个字记得更牢——从字源理解汉字。', era: '汉 ~ 当代', imageKeyword: 'zili literacy character origin', fullContent: '字理识字是通过讲解字源、字形演变、构字理据来识记汉字的方法。例如"明"从日月，光明之意；"暮"从日莫（莫即林），日落林中；"休"从人木，人依树而息。理解字理后，字形与字义直接挂钩，记得牢、用得活。字理识字是当代汉字教学的重要方法。' },
  { id: 'tr-script-natural', category: 'script', title: '汉字里的自然万物', summary: '字是写生画——日雨艹木皆可观。', era: '商 ~ 当代', imageKeyword: 'chinese character nature', fullContent: '汉字保留了大量自然万物的形态。日、雨、雪、雾、雷、电、风、云——气象万千；艹、木、林、森、根、叶、花、果——草木葱茏；山、丘、岭、峰、谷、江、河、海、川——山河壮丽。每一个字都是一幅"写生画"，都浓缩着古人对自然的观察与审美。' },
  { id: 'tr-script-history', category: 'script', title: '汉字里的人文历史', summary: '字是活文物——字形演变映射文明轨迹。', era: '商 ~ 当代', imageKeyword: 'chinese character history', fullContent: '汉字是活的文物。从甲骨文到楷书，三千年的字形演变映射了文明演进。甲骨文记商王占卜，金文记周王诰命，篆书记秦帝一统，隶书记汉代文书，楷书记唐诗宋词——每个时代的字形都反映那个时代的政治、制度、审美。"字是活文物"，一个汉字就是一部微缩史。' },
  { id: 'tr-script-life', category: 'script', title: '汉字里的衣食住行', summary: '字是老照片——吃穿住行在字里活过来。', era: '商 ~ 当代', imageKeyword: 'chinese character daily life', fullContent: '衣食住行的汉字像老照片。衣——裘、衫、裙、袍；食——饭、粥、羹、炙、煮、蒸、酿；住——宅、室、宫、殿、堂、廊；行——车、舟、轿、马、路、桥。每一个字都是生活场景的定格。"字是老照片"，字里住着古人活生生的日子。' },
  { id: 'tr-script-writing', category: 'script', title: '汉字的书写', summary: '汉字里的空间结构艺术——横竖撇捺的视觉哲学。', era: '商 ~ 当代', imageKeyword: 'chinese calligraphy writing', fullContent: '汉字书写不仅是记录，更是艺术。横（平）、竖（直）、撇（掠）、捺（磔）、点（侧）、钩（趯）、提（策）、折（转）——八种基本笔画构成万千汉字。结构上讲究"避就""穿插""向背""呼应"。汉字的空间结构艺术，是世界上独一无二的视觉哲学。' },
  { id: 'tr-script-wrong', category: 'script', title: '那些有名的错别字', summary: '错也错得有理有据——通假字避讳字与历史错用。', era: '先秦 ~ 当代', imageKeyword: 'chinese character homonym', fullContent: '有些"错别字"是有理有据的：通假字——古时通用假借，如"早"作"蚤"、"说"作"悦"；避讳字——为避帝王名讳而改字，如康熙名玄烨，清代"玄"改写为"元"。此外还有书法中的"碑别字"、刻板中的"讹字"。"错也错得有理有据"——错别字背后是历史。' },
  { id: 'tr-script-sanzijing', category: 'script', title: '朗朗上口的《三字经》', summary: '古代孩童的启蒙书——人之初性本善。', era: '宋 ~ 当代', imageKeyword: 'sanzijing three character classic', fullContent: '《三字经》南宋王应麟撰（一说宋末区适子），三字一句，共 1000 多字。"人之初，性本善。性相近，习相远。苟不教，性乃迁。"——朗朗上口，涵盖天文、地理、伦理、历史、典故，是古代孩童最重要的蒙学经典，与《百家姓》《千字文》并称"三百千"。' },
  { id: 'tr-script-baijiaxing', category: 'script', title: '华夏的族谱百姓姓', summary: '一本书留存中华姓氏文化——单姓复姓少数民族姓。', era: '宋', imageKeyword: 'baijiaxing hundred surnames', fullContent: '《百家姓》北宋初年编，收 504 姓（408 单姓，30 复姓），"赵钱孙李，周吴郑王"开篇。"赵"排第一因编者宋初帝王姓赵。中华姓氏承载血缘、宗族、地理——李、王、张、刘、陈为当代五大姓。复姓如司马、欧阳、上官、令狐。少数民族姓如蒙古、满、回。' },
  { id: 'tr-script-qianziwen', category: 'script', title: '包罗万象的《千字文》', summary: '一千个不重复的字组成了一本书——天地玄黄宇宙洪荒。', era: '南朝', imageKeyword: 'qianziwen thousand character', fullContent: '《千字文》南朝周兴嗣编（一说梁武帝命编）。将王羲之书法残字 1000 个（无一重复）编为四言韵文："天地玄黄，宇宙洪荒，日月盈昃，辰宿列张……"涵盖天文、地理、伦理、历史、修身，是世界上唯一无重复字的文章，也是蒙学必读。' },
  { id: 'tr-script-duilian', category: 'script', title: '文字的游戏对对联', summary: '要的就是工整平仄押韵——对联是中文独有的艺术。', era: '五代 ~ 当代', imageKeyword: 'duilian couplet parallel', fullContent: '对联又称楹联、对子，五代后蜀孟昶"新年纳余庆，嘉节号长春"是中国第一副春联。对联讲究：字数相等、词性相对、平仄相对、押韵、上下联不重复。"两个黄鹂鸣翠柳，一行白鹭上青天"——诗可作对。对联是中文独有的语言艺术，春节、婚丧、庙宇必有对联。' },
  { id: 'tr-script-chengyu', category: 'script', title: '引经据典的成语', summary: '语言中的压缩包——四字浓缩千年故事。', era: '先秦 ~ 当代', imageKeyword: 'chengyu four character idiom', fullContent: '成语大多四字，出自古代典籍。"破釜沉舟"（项羽）、"完璧归赵"（蔺相如）、"草木皆兵"（淝水之战）、"杯弓蛇影"（汉代）。成语是语言中的"压缩包"——四字浓缩一个故事、一个道理。约 5 万条成语承载中华历史、哲学、文学。' },
  { id: 'tr-script-suyu', category: 'script', title: '有趣的民间俗语', summary: '民间的智慧也很无敌——谚语俗话歇后语。', era: '先秦 ~ 当代', imageKeyword: 'suyu proverb folk saying', fullContent: '俗语是民间集体智慧的结晶。谚语——"早起的鸟儿有虫吃""失败是成功之母"；俗话——"三百六十行，行行出状元""远亲不如近邻"；歇后语——"猫哭耗子——假慈悲""竹篮打水——一场空"。民间的智慧也很无敌——它比文言更鲜活，比成语更生活。' },
  { id: 'tr-script-books', category: 'script', title: '文化的承载书籍', summary: '书籍是人类进步的阶梯——从竹简到电子书。', era: '先秦 ~ 当代', imageKeyword: 'books chinese history', fullContent: '书籍是文化的载体。从先秦竹简（"韦编三绝"孔子读《易》）、到东汉蔡伦纸书、唐雕版印刷、宋代毕昇活字印刷、明清线装书，到当代电子书。书籍形制的变迁映射技术与审美的演进。"书籍是人类进步的阶梯"——高尔基说，但中华典籍三千年的积累更深刻。' },
  { id: 'tr-script-jingshi', category: 'script', title: '经史子集', summary: '古人的图书分类法——四部分类影响中华千年。', era: '唐 ~ 清', imageKeyword: 'jingshi ziji four parts', fullContent: '经史子集是中国传统图书的四部分类法——《四库全书》总目以此编排。经——儒家经典（诗书礼易春秋）；史——历史著作（史记、汉书等二十四史）；子——诸子百家（儒释道墨法等）；集——诗词文集（楚辞、汉赋、唐诗、宋词等）。四部分类从《隋书·经籍志》定型，到清代《四库全书》达到顶峰。' },
  { id: 'tr-script-baihua', category: 'script', title: '从文言文到白话文', summary: '书面语从庙堂走向街头巷尾——五四白话文革命。', era: '新文化运动', imageKeyword: 'baihua vernacular chinese', fullContent: '1917 年胡适《文学改良刍议》提倡白话文，1919 年五四运动后白话文迅速普及。文言文是士大夫的书面语（"之乎者也"），白话文是民众的口头语（"我你他"）。白话文运动使书面语从庙堂走向街头巷尾，让教育普及成为可能。"我手写我口"——胡适的主张影响了整个现代汉语。' },
{ id: 'tr-literature-1', category: 'literature', title: '诗经楚辞', summary: '中国文学的两大源头：黄河的现实主义与长江的浪漫主义。', era: '先秦' },
  { id: 'tr-literature-2', category: 'literature', title: '唐诗宋词', summary: '一个把诗写到极致、把词写到骨子里的时代。', era: '唐 ~ 宋' },
  { id: 'tr-literature-3', category: 'literature', title: '四大名著', summary: '《三国》《水浒》《西游》《红楼》——章回小说的巅峰。', era: '明 ~ 清' },
  // art (3)
  { id: 'tr-art-1', category: 'art', title: '山水画', summary: '从展子虞到王希孟——中国人如何用毛笔"看"山水。', era: '魏晋 ~ 当代' },
  { id: 'tr-art-2', category: 'art', title: '青花瓷', summary: '白地蓝花，从元代走向世界——陶瓷工艺的极致。', era: '元 ~ 清' },
  { id: 'tr-art-3', category: 'art', title: '园林', summary: '移步换景，咫尺山林——中国独特的空间美学。', era: '明 ~ 清' },
  // calendar (3)
  { id: 'tr-calendar-1', category: 'calendar', title: '农历（夏历）', summary: '阴阳合历：月相定月、太阳定年——指导农耕数千年。', era: '夏 ~ 当代' },
  { id: 'tr-calendar-2', category: 'calendar', title: '二十四节气', summary: '立春、惊蛰、清明……太阳在黄道上的 24 个刻度，已列入人类非遗。', era: '先秦 ~ 当代' },
  { id: 'tr-calendar-3', category: 'calendar', title: '干支纪年', summary: '天干地支 60 年一轮——纪年、纪月、纪日、纪时皆用之。', era: '殷商 ~ 当代' },
  // ritual (3)
  { id: 'tr-ritual-1', category: 'ritual', title: '科举制度', summary: '从隋唐到清末 1300 年——"朝为田舍郎，暮登天子堂"的社会流动机制。', era: '隋 ~ 清' },
  { id: 'tr-ritual-2', category: 'ritual', title: '五礼制度', summary: '吉、凶、军、宾、嘉——覆盖政治、社会、人生所有仪节。', era: '先秦 ~ 清' },
  { id: 'tr-ritual-3', category: 'ritual', title: '礼与法', summary: '"礼者禁于将然之前，法者禁于已然之后"——德治与法治的双轨。', era: '先秦 ~ 当代' },
  // food (3)
  { id: 'tr-food-1', category: 'food', title: '八大菜系', summary: '鲁川粤苏闽浙湘徽——四方水土养出四方滋味。', era: '清 ~ 当代' },
  { id: 'tr-food-2', category: 'food', title: '丝绸与棉麻', summary: '从桑蚕到棉花——中国人 5000 年的纤维革命。', era: '新石器 ~ 当代' },
  { id: 'tr-food-3', category: 'food', title: '茶', summary: '从神农尝百草到陆羽《茶经》——一片树叶如何成为国饮。', era: '唐 ~ 当代' },
  // housing (3)
  { id: 'tr-housing-1', category: 'housing', title: '四合院', summary: '北方的合院式住宅：方正对称、伦理秩序、长幼有序。', era: '元 ~ 当代' },
  { id: 'tr-housing-2', category: 'housing', title: '江南水乡', summary: '粉墙黛瓦、小桥流水——水网地带的人居智慧。', era: '明 ~ 当代' },
  { id: 'tr-housing-3', category: 'housing', title: '交通工具', summary: '舟车、轿马、独轮车、漕运——传统中国的出行图谱。', era: '先秦 ~ 清' },
  // tech (4)
  { id: 'tr-tech-1', category: 'tech', title: '四大发明', summary: '造纸、印刷、火药、指南针——重塑世界历史的四项技术。', era: '汉 ~ 宋' },
  { id: 'tr-tech-2', category: 'tech', title: '天文历法', summary: '从甲骨卜辞到郭守敬《授时历》——世界上连续最久的天文观测。', era: '商 ~ 元' },
  { id: 'tr-tech-3', category: 'tech', title: '中医中药', summary: '《黄帝内经》《伤寒论》、针灸、本草——以另一种方式理解人体。', era: '先秦 ~ 当代' },
  { id: 'tr-tech-4', category: 'tech', title: '水利与农业', summary: '都江堰、坎儿井、桑基鱼塘——水利工程塑造农业文明。', era: '先秦 ~ 当代' },

  // geography-regional (30 — 第1页行政区划+北方 11 + 第2页各地域 19)
  { id: 'tr-region-intro', category: 'geography-regional', title: '引子', summary: '中国人的家 — 地理、血缘、文化三重意义上的“家“，是安身立命之所。', era: '亘古至今', imageKeyword: 'chinese homeland culture family', fullContent: '中国人谈“家“，往往包含三层含义：地理上的故土、血缘上的宗族、文化上的籍贯。既有安土重迁的农耕情结，也有“举头望明月，低头思故乡“的游子情怀；既讲“修齐治平“的家国天下，也讲“父母在，不远游“的伦理本位。从一片土地到一个姓氏再到一种方言，“家“塑造了我们理解世界的方式。' },
  { id: 'tr-region-jiuzhou', category: 'geography-regional', title: '天下九州', summary: '古老的华夏九州还在吗？源自《禹贡》的地理区划，影响后世三千年。', era: 'BC 2000 ~ 今', imageKeyword: 'jiuzhou nine provinces ancient china', fullContent: '“九州“最早见于《禹贡》，将天下划分为冀、兖、青、徐、扬、荆、豫、梁、雍九州，对应大禹治水后的地理认知。这一划分虽不严格对应行政区划，却奠定了中国人“天下“的原型：冀州为华夏之中心，扬州为东南之尾，雍州据西北之险。九州概念影响三千年，李白“九州生气恃风雷“、陆游“但悲不见九州同“皆引此意象。' },
  { id: 'tr-region-xingsheng', category: 'geography-regional', title: '从氏族部落到行省', summary: '“省“是怎么来的？从部落联盟到州郡，再到行省制——地方治理的演化。', era: '先秦 ~ 当代', imageKeyword: 'xing sheng provinces chinese governance', fullContent: '中国地方治理经历漫长演化：远古部落联盟以血缘为纽带，夏商周封建以宗法分封；秦废封建设郡县；汉沿用郡国并行；隋唐设州县、道；宋设路；元朝创立“行中书省“，即“行省“，今日省制由此奠基。明清沿用并细化为府州县，省界犬牙交错以防割据。今日中国 23 省之格局，是三千年演化的结果。' },
  { id: 'tr-region-fangqu', category: 'geography-regional', title: '山川形便和犬牙交错', summary: '中国古代行政区域划界两大原则——前者顺自然地形，后者防割据。', era: '秦 ~ 清', imageKeyword: 'chinese administrative boundaries history', fullContent: '“山川形便“以山脉、河流等自然地形为界，便于治理也符合经济文化圈；“犬牙交错“则故意打破自然边界，把不同地形区域划入同一行政区，防止地方凭借天险割据。汉武帝拆分“关中“、宋太宗让“秦凤“与“永兴“穿插、明代让湖广跨洞庭湖分南北——都是“犬牙交错“的经典案例。今日省界多承明清之制，正是这两条原则博弈的结果。' },
  { id: 'tr-region-dusheng', category: 'geography-regional', title: '历史上的都城', summary: '古人建都要“看风水“——从长安、洛阳到北京、南京，城市与权力中心。', era: 'BC 1046 ~ 1912', imageKeyword: 'chinese ancient capital changan luoyang beijing', fullContent: '中国古都讲究“龙脉“、“形胜“：长安据关中四塞，“山河襟带“；洛阳居天下之中，“宅中图大“；开封控汴河漕运之利；南京龙蟠虎踞；北京背靠燕山、南望中原。八大古都(西安、洛阳、北京、南京、开封、杭州、安阳、郑州)各有风水逻辑。从周到清，都城迁移反映经济重心由西向东、由北向南的转移轨迹。' },
  { id: 'tr-region-nanbei', category: 'geography-regional', title: '中国文化的“南北之争”', summary: '中国的南方北方到底指哪儿？秦岭-淮河线、南船北马、南米北面。', era: 'BC ~ 当代', imageKeyword: 'north south china culture difference', fullContent: '“秦岭-淮河“是中国最重要的南北分界线：此线以北属温带，旱地种麦、骑马出行、性格豪迈；此线以南属亚热带，水田种稻、行舟代步、性格细腻。“南船北马“、“南米北面“、“南甜北咸“、“南柔北刚“——这些差异源于地理气候。但中国南北之争并非绝对：江淮之间是过渡带，北方亦多细腻之人。今日方言、饮食、文学风格的差异，仍清晰可辨。' },
  { id: 'tr-region-overview', category: 'geography-regional', title: '地域文化', summary: '百里不同风，千里不同俗——中国地理与文化的多样性。', era: '亘古至今', imageKeyword: 'chinese regional culture diversity', fullContent: '“地域文化“指因地理环境、历史沿革、民族分布不同而形成的区域文化。中国地域文化类型丰富：以燕赵、齐鲁、三晋为代表的北方文化；以荆楚、巴蜀、吴越为代表的中部文化；以岭南、闽台为代表的南方文化；以及关东、关中、西域、雪域等边缘文化。各地域文化既有中华共性，又保留鲜明个性——饮食、方言、民俗、艺术、建筑皆可印证。' },
  { id: 'tr-region-yanzhao', category: 'geography-regional', title: '燕赵文化', summary: '燕赵之地自古多豪杰——河北、京津的慷慨悲歌与侠义精神。', era: '先秦 ~ 当代', imageKeyword: 'yanzhao culture hebei beijing', fullContent: '“燕赵“指今河北、北京、天津及山西东北部。战国时燕赵为北方军事强国，“燕赵多慷慨悲歌之士“(韩愈)。荆轲刺秦“风萧萧兮易水寒“、赵云长坂坡单骑救主，皆此地风骨。京畿文化大气规整——紫禁城、天坛、颐和园；河北古朴豪放——赵州桥、承德避暑山庄、直隶总督署；天津则以漕运、租界、洋务文化见长。' },
  { id: 'tr-region-shanjin', category: 'geography-regional', title: '三晋文化', summary: '中国古建文化集大成者——山西的晋商大院、彩塑壁画、云冈石窟。', era: '唐 ~ 当代', imageKeyword: 'shanjin culture shanxi ancient architecture', fullContent: '“三晋“指今山西，源自韩、赵、魏三家分晋。山西是中国古建博物馆：唐代建筑全国现存四座全在山西(南禅寺、佛光寺等)；云冈石窟凿于北魏；晋祠、应县木塔、平遥古城为世界文化遗产。晋商崛起于明清，乔家大院、王家大院、常家庄园见证“汇通天下“的辉煌。山西梆子(晋剧)、面食(刀削面、莜面栲栳栳)亦独具特色。' },
  { id: 'tr-region-qilu', category: 'geography-regional', title: '齐鲁文化', summary: '千年教育、思想、文化归齐鲁——孔孟之乡，儒家发源地。', era: 'BC 1046 ~ 当代', imageKeyword: 'qilu culture confucius shandong', fullContent: '“齐鲁“指今山东。周公封于鲁、齐太公封于齐，鲁崇礼、齐尚功。儒家创始人孔子(鲁)、孟子(邹)皆出此地，曲阜“三孔“(孔庙、孔府、孔林)是朝圣中心。泰山为五岳之首，封禅之地；崂山为道教名山。鲁菜为中国八大菜系之首，济南菜、胶东菜、孔府菜各有千秋。山东人豪爽好客、崇文重教，古代出过无数状元宰相。' },
  { id: 'tr-region-guandong', category: 'geography-regional', title: '关东文化', summary: '虽冷但热闹的大东北——白山黑水，满、汉、朝鲜族多元融合。', era: '唐 ~ 当代', imageKeyword: 'guandong culture northeast china', fullContent: '“关东“指山海关以东的东北三省(辽、吉、黑)及内蒙古东部。“白山黑水“孕育了肃慎、扶余、勿吉、靺鞨、女真等古代民族。女真人建金、后金(清)两度入主中原。闯关东是近代东北开发的关键，儒商、农耕文化与渔猎、游牧文化交融。今日东北话、二人转、东北菜(锅包肉、杀猪菜)、工业遗产与俄式建筑并存，朝鲜族、满族文化独具特色。' },
  { id: 'tr-region-neimenggu', category: 'geography-regional', title: '内蒙古草原文化', summary: '天苍苍，野茫茫，风吹草低见牛羊——游牧文明与草原精神。', era: '秦 ~ 当代', imageKeyword: 'inner mongolia grassland culture nomadic', fullContent: '内蒙古高原东起大兴安岭、西至额济纳，是游牧文明的摇篮。匈奴、鲜卑、突厥、蒙古等民族先后在此崛起。蒙古包、勒勒车、长调、呼麦、马头琴是草原文化的标志；那达慕大会承载摔跤、赛马、射箭传统。草原文化与中原农耕文化既冲突又交融——和亲、互市、战争贯穿史册。今日内蒙古仍以“风吹草低见牛羊“的壮美风光与豪迈民风著称。' },
  { id: 'tr-region-zhongzhou', category: 'geography-regional', title: '中州文化', summary: '若问古今兴废事，请看中州大地——河南中原，华夏文明腹地。', era: 'BC 2000 ~ 当代', imageKeyword: 'zhongzhou culture henan yellow river', fullContent: '“中州“指今河南，因居天下之中而得名。河南是华夏文明的腹地：裴李岗、仰韶、龙山、二里头、殷墟—安阳(商)、洛阳(十三朝古都)、开封(七朝古都)、郑州(商城)皆在河南。河洛文明是中华文明的源头，洛阳龙门石窟、嵩山少林寺、开封清明上河图、白马寺、龙门书院享誉中外。豫剧、少林功夫、汴绣、洛阳牡丹是地域文化名片。' },
  { id: 'tr-region-hui', category: 'geography-regional', title: '徽文化', summary: '十户之村不废诵读——徽商、徽派建筑、徽州朴学的皖南文化。', era: '宋 ~ 当代', imageKeyword: 'hui culture anhui merchant architecture', fullContent: '“徽文化“指皖南古徽州(今黄山市、绩溪、婺源)文化。徽商崛起于明清，与晋商齐名，“无徽不成镇“——扬州、苏州、汉口皆赖徽商繁荣。徽派建筑以白墙黛瓦、马头墙、天井为特色，西递、宏村是世界文化遗产。“徽州朴学“(乾嘉考据学派)严谨求实；新安画派、徽剧(京剧前身之一)、歙砚、徽墨皆为文化瑰宝。“十户之村不废诵读“是徽州崇文传统的写照。' },
  { id: 'tr-region-jiangxi', category: 'geography-regional', title: '江西文化', summary: '物华天宝，人杰地灵——赣鄱大地，陶渊明、王安石故里。', era: '唐 ~ 当代', imageKeyword: 'jiangxi culture ganpo tao yuanming', fullContent: '江西因赣江纵贯、鄱阳湖为最大淡水湖而简称“赣“或“赣鄱“。唐宋时期江西文化鼎盛：王勃《滕王阁序》“物华天宝，人杰地灵“千古传诵；陶渊明(九江)、王安石(抚州)、欧阳修(吉安)、文天祥(吉安)、黄庭坚(修水)皆出此地。白鹿洞书院为宋代四大书院之首；景德镇自宋元即为“瓷都“，青花、玲珑、粉彩、颜色釉冠绝天下。赣剧、采茶戏亦有特色。' },
  { id: 'tr-region-jingchu', category: 'geography-regional', title: '荆楚文化', summary: '路漫漫其修远兮，吾将上下而求索——湖北楚地，屈原精神。', era: '先秦 ~ 当代', imageKeyword: 'jingchu culture hubei chu qu yuan', fullContent: '“荆楚“指今湖北及湖南北部。楚人“筚路蓝缕，以启山林“，从祝融部落发展为春秋五霸、战国七雄之一。屈原《离骚》、《天问》、《九歌》开创楚辞，与《诗经》并称文学双壁；编钟(随州曾侯乙编钟)、漆器、丝织、楚绣是工艺代表。湖北九省通衢，武汉为辛亥革命首义之地；武当山道教圣地，黄鹤楼千古名楼。' },
  { id: 'tr-region-huxiang', category: 'geography-regional', title: '湖湘文化', summary: '潇湘美景都是诗——湖南湘楚，近代革命策源地。', era: '唐 ~ 当代', imageKeyword: 'huxiang culture hunan xiang', fullContent: '“湖湘“指今湖南。屈原《九歌》多咏潇湘。湖湘文化经世致用、心忧天下：周敦颐、王夫之、魏源、曾国藩、左宗棠、谭嗣同、黄兴、毛泽东、蔡锷皆出此地。岳麓书院“惟楚有材，于斯为盛“千年文脉。湖南人“敢为天下先“——太平天国、维新变法、辛亥革命、秋收起义皆与湘人相关。湘菜(剁椒鱼头、毛氏红烧肉)、花鼓戏、湘绣、浏阳花炮是地域标志。' },
  { id: 'tr-region-wuyue', category: 'geography-regional', title: '吴越文化', summary: '江南好，风景旧曾谙——江浙沪，吴侬软语与精致文雅。', era: '先秦 ~ 当代', imageKeyword: 'wuyue culture jiangsu zhejiang jiangnan', fullContent: '“吴越“指今江苏南部、浙江、上海及皖东南。“江南“是吴越文化的核心：苏州园林、杭州西湖、无锡太湖、绍兴兰亭皆人文渊薮。吴语(苏州话、上海话、绍兴话)以软糯著称；昆曲、评弹、苏绣、越剧、龙泉青瓷、湖笔、宣纸、湖州丝绸冠绝天下。江浙历代状元、院士人数冠全国，文人墨客辈出。江南文化精致、文雅、崇文、重商。' },
  { id: 'tr-region-min', category: 'geography-regional', title: '闽文化', summary: '山地文明和海洋文明的交汇——福建莆仙、闽南、客家、妈祖。', era: '唐 ~ 当代', imageKeyword: 'min culture fujian fuzhou xiamen', fullContent: '“闽“指福建，多山面海，“八山一水一分田“。闽文化分为闽东(福州)、闽南(厦门、泉州)、莆仙、闽北、闽西客家、畲族等亚文化。泉州为宋元“东方第一大港“，马可·波罗笔下的“光明之城“，海上丝绸之路起点。闽南话(河洛话)被称为“古汉语活化石“。妈祖信仰从莆田湄洲传至全球华人与东南亚；土楼(永定、南靖)是客家文化瑰宝。闽菜以海鲜、汤品著称。' },
  { id: 'tr-region-lingnan', category: 'geography-regional', title: '岭南文化', summary: '逛花市，喝早茶，不辞长作岭南人——广东、广西的海洋商业文化。', era: '秦 ~ 当代', imageKeyword: 'lingnan culture guangdong canton', fullContent: '“岭南“指五岭以南的广东、广西、海南、香港、澳门。岭南文化以海洋、商业、开放为特色：粤语保留古音；广府、客家、潮汕、雷州四大民系多元并存。早茶文化、煲汤、生猛海鲜、粤菜(八大菜系之一)闻名天下。广绣、潮绣、端砚、广东音乐、粤剧、岭南画派(高剑父)文化独特。广州十三行见证清代外贸繁荣；深圳、珠海引领改革开放。' },
  { id: 'tr-region-gui', category: 'geography-regional', title: '桂文化', summary: '去广西看多彩的少数民族风情——壮、侗、苗、瑶等众多少数民族。', era: '唐 ~ 当代', imageKeyword: 'guangxi culture minority zhuang', fullContent: '“桂“指广西，简称“桂“，因桂林而闻名。广西是中国少数民族最多的省区之一：壮族占 32%，侗、苗、瑶、彝、京、仫佬、毛南、回等 11 个世居民族。桂林山水甲天下，漓江、阳朔、兴安灵渠、龙脊梯田是自然人文奇观。壮族“三月三“歌节、铜鼓楼(侗族)、风雨桥、壮锦、绣球是地域标志。桂北与桂南文化差异显著，桂林文化更接近湘楚，东南部靠近粤文化。' },
  { id: 'tr-region-dianyun', category: 'geography-regional', title: '滇云文化', summary: '靠山吃山，靠水吃水——云南 25 个世居民族的多元文化。', era: '先秦 ~ 当代', imageKeyword: 'yunnan dianyun culture minority', fullContent: '“滇云“指云南，是中国民族最多的省份——25 个世居民族、16 个跨境民族。滇池周边是古滇国故地，晋宁石寨山青铜器见证古滇文明。东巴文(纳西族)被誉为“活着的象形文字“。大理国(白族)与南诏国绵延千年；丽江古城为世界文化遗产；西双版纳傣族泼水节、彝族火把节、白族三道茶、哈尼梯田(红河)展现多彩风情。云南是“人类学博物馆“，也是茶马古道、南方丝绸之路要冲。' },
  { id: 'tr-region-qiangui', category: 'geography-regional', title: '黔贵文化', summary: '“惟尔贵州，远在要荒“——贵州的山地民族与夜郎文化。', era: '先秦 ~ 当代', imageKeyword: 'guizhou qiangui culture minority', fullContent: '“黔“或“贵“指贵州，古为“夜郎国“。“夜郎自大“虽为贬义，却反映云贵高原少数民族的独立个性。贵州地形破碎，山地占 92%，孕育独特山地文化：苗族(西江千户苗寨)、侗族(鼓楼、风雨桥)、布依族、彝族、土家族、仡佬族多元共生。黄果树瀑布、荔波喀斯特、赤水丹霞、梵净山是世界级自然遗产；茅台酒、都匀毛尖享誉天下；侗族大歌为人类非物质文化遗产。' },
  { id: 'tr-region-bashu', category: 'geography-regional', title: '巴蜀文化', summary: '“蜀道之难，难于上青天“——川渝的天府之国与巴蜀文明。', era: '先秦 ~ 当代', imageKeyword: 'bashu culture sichuan chongqing', fullContent: '“巴蜀“指四川、重庆。三星堆、金沙遗址显示巴蜀文明独立于中原。李白“蜀道之难，难于上青天“道尽此地险阻。都江堰水利工程使成都平原“水旱从人，不知饥馑“，故有“天府之国“美名。川菜(川渝为中国“美食之都“)、川剧变脸、川酒(五粮液、泸州老窖)、蜀绣享誉天下。大熊猫是文化符号。武侯祠、杜甫草堂、三苏祠承载文脉；重庆火锅、码头文化独成一派。' },
  { id: 'tr-region-sanqin', category: 'geography-regional', title: '三秦文化', summary: '“城阙辅三秦，风烟望五津“——陕西关中，长安所在的帝王州。', era: 'BC 1046 ~ 当代', imageKeyword: 'sanqin culture shaanxi changan', fullContent: '“三秦“指今陕西关中、陕北，项羽分封“三秦王“沿用之。关中是周、秦、汉、唐等十三朝建都之地，长安(今西安)是当时世界最大都市。秦始皇陵、兵马俑、汉武帝茂陵、唐太宗昭陵、武则天乾陵世界闻名。西岳华山险峻，壶口瀑布雄浑，延安是中国革命圣地。秦腔、陕北秧歌、信天游、皮影、安塞腰鼓是地域标志；羊肉泡馍、肉夹馍、岐山臊子面是关中味道。' },
  { id: 'tr-region-ganlong', category: 'geography-regional', title: '甘陇文化', summary: '“黄河远上白云间，一片孤城万仞山“——甘肃陇右丝路与黄河文明。', era: '汉 ~ 当代', imageKeyword: 'ganlong culture gansu silk road', fullContent: '“甘陇“指甘肃。甘肃是黄河文明、丝路文化、长城文化交汇之地。河西走廊是丝绸之路咽喉：武威、张掖、酒泉、敦煌四郡贯穿东西；敦煌莫高窟、麦积山石窟、嘉峪关城楼世界闻名。伏羲(天水)、女娲(秦安)、周祖(庆阳)、秦皇(礼县)皆出陇上。陇东窑洞、陇南山水、河西走廊大漠戈壁、祁连雪山、陇中黄土高原多彩并存。兰州牛肉面享誉全球；花儿(民歌)、陇剧、太平鼓具地方特色。' },
  { id: 'tr-region-ningxia', category: 'geography-regional', title: '宁夏文化', summary: '历史上的西夏——贺兰山下党项羌建立的 190 年王朝。', era: 'AD 1038-1227', imageKeyword: 'ningxia culture western xia tangut', fullContent: '宁夏以“贺兰山下果园成，塞北江南旧有名“著称。1038 年党项羌李元昊建立西夏，定都兴庆府(银川)，立国 190 年，与宋、辽、金鼎立。西夏创制西夏文，仿汉字而结构独特，是中国唯一被发现的“死文字“。1227 年蒙古灭西夏。贺兰山岩画记录远古游牧生活；西夏王陵是中国现存规模最大、地面遗迹最完整的帝王陵园之一。回族约占宁夏 1/3，伊斯兰文化与黄河灌溉农业(宁夏平原)交融。' },
  { id: 'tr-region-xinjiang', category: 'geography-regional', title: '新疆文化', summary: '最美的风景在新疆——三山两盆，47 个民族，丝路咽喉。', era: '汉 ~ 当代', imageKeyword: 'xinjiang culture uyghur silk road', fullContent: '新疆“三山夹两盆“——阿尔泰山、天山、昆仑山，准噶尔盆地、塔里木盆地。公元前 2 世纪起即为丝绸之路要冲，龟兹、于阗、楼兰、高昌等绿洲城邦见证东西文明交融。维吾尔、哈萨克、柯尔克孜、塔吉克、蒙古、锡伯、汉等 47 个民族共居。喀什噶尔老城、艾提尕尔清真寺、克孜尔石窟、柏孜克里克千佛洞、交河故城、楼兰遗址是丝路遗珍。维吾尔族十二木卡姆、《玛纳斯》、《江格尔》三大史诗传世。' },
  { id: 'tr-region-zang', category: 'geography-regional', title: '青藏高原藏文化', summary: '生活在雪域高原上的民族——藏传佛教、雪山牧场、独特生态。', era: '唐 ~ 当代', imageKeyword: 'tibet qinghai culture himalaya', fullContent: '青藏高原是世界屋脊，平均海拔 4000 米以上。藏文化以藏传佛教(格鲁派、宁玛派、噶举派、萨迦派)为核心，布达拉宫、大昭寺、扎什伦布寺、塔尔寺是信仰中心。吐蕃王朝(7-9 世纪)曾雄踞高原，与唐争衡；藏文创制于松赞干布时期，文成公主入藏和亲传为佳话。青稞、牦牛、酥油茶、糌粑、转经筒、玛尼堆、唐卡、藏戏是文化标志。藏族人民坚毅、虔敬、与自然和谐共处的精神代代相传。' },
  { id: 'tr-region-hehuang', category: 'geography-regional', title: '河湟文化', summary: '回到黄河上游——甘青交界，多民族交汇过渡带。', era: '汉 ~ 当代', imageKeyword: 'hehuang culture yellow river upper', fullContent: '“河湟“指黄河上游与湟水流域，即今青海东部、甘肃西部、宁夏西部的交汇地带。这一区域是黄土高原、青藏高原、内蒙古高原的过渡带，汉、藏、回、土、撒拉、蒙古多民族杂居。河湟文化兼具中原农耕、藏传佛教、伊斯兰文化元素：塔尔寺(藏传佛教格鲁派六大寺院之一)、西宁东关清真大寺、瞿昙寺、柳湾彩陶遗址、马家窑文化遗址皆在此。汉、藏、回、撒拉、土族共同塑造了河湟多元一体的文化格局。' },
]
